mapper.update:
UPDATE sys01_company
   SET sys01_leave_yn       = #{leaveYn},
       sys01_leave_month_cd = #{leaveMonthCode}
 WHERE sys01_company_id = #{companyId}

UPDATE sys30_leave_year
   SET sys30_year       = CAST(#{req.year} AS numeric),
       sys30_leave_days = CAST(#{req.leaveDays} AS numeric)
 WHERE sys30_leave_year_id = #{req.leaveYearId}
   AND sys30_company_id    = #{companyId}

mapper.delete:
DELETE FROM sys30_leave_year
 WHERE sys30_company_id = #{companyId}
   AND sys30_leave_year_id IN
#{leaveYearId}
